      ui.label(s,6,h-20,graph.status or "",w-12,p.muted,p.panel)
    else
      local rows=self.page=="targets" and filter.targets(snap.targets,self.filters) or self.page=="cannons" and snap.cannons or self.page=="network" and (self.networkSnapshot or {}).nodes or snap.devices
      local top=51 local capacity=math.max(1,math.floor((h-116)/(self.page=="probe" and 52 or 26)))
      self.scroll=math.max(1,math.min(self.scroll,math.max(1,#(rows or {})-capacity+1)))
      if self.page=="fire" then
        local target=find(snap.targets,self.targetId) local cannon=find(snap.cannons,self.cannonId)
        local lines={"Cannon: "..tostring(cannon and cannon.name or "none"),"Target: "..tostring(target and target.label or "none"),
          "Mode: semi-auto / manual fire confirmation",self.solution and ("ESTIMATE: yaw "..num(self.solution.yaw).." / pitch "..num(self.solution.pitch).." (vacuum)") or "No verified solution"}
        for i,line in ipairs(lines) do ui.label(s,8,top+(i-1)*20,line,w-16,p.text,p.panel) end
      else
        for i=self.scroll,math.min(#(rows or {}),self.scroll+capacity-1) do
          local row=rows[i] local id=row.id or row.name
          local label=tostring(row.label or row.name or id)
          if self.page=="targets" then label=label.." | "..filter.category(row)..(row.stale and " | STALE" or "") end
          if self.page=="cannons" then label=label.." | yaw "..num(row.yaw).." / pitch "..num(row.pitch).." | assembled "..tostring(row.assembled) end
          if self.page=="network" then label=label..(row.included and " | included" or " | excluded")..(row.online and " | online" or " | offline") end
          button("row:"..i,label,rect(6,top+(i-self.scroll)*26,w-12,24),id==self.targetId or id==self.cannonId or id==self.deviceId)
        end
        if #(rows or {})==0 then ui.label(s,8,top,"No devices / contacts",w-16,p.muted,p.panel) end
      end
      if self.page=="probe" then
        local device=find(rows,self.deviceId)
        local y=top+capacity*26+8
        ui.label(s,8,y,"Methods: "..table.concat(device and device.methods or {},", "),w-16,p.accent,p.panel)
        local probe=snap.probe
        if probe and probe.name==self.deviceId then
          local values={}
          for key,value in pairs(probe.values or {}) do
            values[#values+1]=key.." = "..(type(value)=="table" and "[table; full data in exported log]" or tostring(value))
          end
          for key,value in pairs(probe.errors or {}) do values[#values+1]=key.." ERROR "..tostring(value) end
          table.sort(values)
          for i,value in ipairs(values) do if y+i*13<h-58 then ui.label(s,8,y+i*13,value,w-16,p.text,p.panel) end end
        end
      end
      local actions=self.page=="fire" and {{"solve","Solve"},{"aim","Aim"},{"track",self.tracking and "Stop" or "Track"},{"fire","Fire"}} or self.page=="network" and {{"networkToggle","Network"},{"publishToggle","Station"},{"networkConfig","Configure"},{"networkRescan","Discover"}} or self.page=="probe" and {{"probe","Read/export"},{"previous","Up"},{"next","Down"}} or {{"previous","Up"},{"next","Down"},{self.page=="targets" and "alias" or "ack",self.page=="targets" and "Alias" or "Verify"}}
      local bx=5 for _,a in ipairs(actions) do local bw=#a[2]*6+16 if bx+bw<w then button(a[1],a[2],rect(bx,h-49,bw,22)) bx=bx+bw+4 end end
      ui.label(s,6,h-20,self.message or "",w-12,p.muted,p.panel)
    end
    if self.nativeViews or self.nativeRadars then
      local mw=math.min(180,w-12) local capacity=math.max(1,math.floor((h-42)/23))
      local rows=self.nativeViews and tabs or snap.radars or {}
      self.nativeViewFirst=math.max(1,math.min(self.nativeViewFirst or 1,math.max(1,#rows-capacity+1)))
      for i=self.nativeViewFirst,math.min(#rows,self.nativeViewFirst+capacity-1) do
        local row=rows[i]
        button(self.nativeViews and "page:"..row.id or "station:"..i,row.label or row.name or row.id,
          rect(5,29+(i-self.nativeViewFirst)*23,mw,22),row.id==(self.nativeViews and self.page or self.radarId))
      end
    end
    if self.confirm then
      self.nativeViews=false self.nativeRadars=false self.nativeHits={} self.nativeContacts={}
      local r=rect(8,math.max(28,math.floor(h/2)-42),w-16,86)
      s:rect(r.x,r.y,r.w,r.h,p.desktop)
      ui.paragraph(s,rect(r.x+8,r.y+7,r.w-16,38),self.confirm.title,p.text,p.desktop,{wrap=true})
      button("confirm","Confirm",rect(r.x+8,r.y+55,78,23)) button("cancel","Cancel",rect(r.x+94,r.y+55,72,23))
    end
  end
  function app:handlePixels(event)
    local x,y=event.args[2],event.args[3]
    if event.name=="key" then
      local key=event.args[1]
      if key==keys.escape then self.nativeViews=false self.nativeRadars=false self.confirm=nil return true end
      if key==keys.tab then
        local hits=self.nativeHits or {} local index=0
        for i,hit in ipairs(hits) do if hit.id==self.nativeFocus then index=i break end end
        if #hits>0 then self.nativeFocus=hits[index%#hits+1].id end
        return true
      end
      if key==keys.enter then
        for _,hit in ipairs(self.nativeHits or {}) do if hit.id==self.nativeFocus then
          return self:handlePixels({name="mouse_click",args={1,hit.rect.x+1,hit.rect.y+1}})
        end end
      end
    end
    if self.confirm and event.name~="mouse_click" then return true end
    if event.name=="mouse_scroll" then
      if self.nativeViews or self.nativeRadars then self.nativeViewFirst=math.max(1,(self.nativeViewFirst or 1)+event.args[1])
      elseif self.page=="radar" or self.page=="three" then api.action(event.args[1]>0 and "zoomOut" or "zoomIn")
      else self.scroll=math.max(1,self.scroll+event.args[1]) end
      return true
    end
    if event.name~="mouse_click" then return false end
    for i=#(self.nativeHits or {}),1,-1 do local hit=self.nativeHits[i] if ui.hit(hit.rect,x,y) then
      local id=hit.id
      if self.confirm then
        if id=="confirm" then local callback=self.confirm.callback self.confirm=nil callback()
        elseif id=="cancel" then self.confirm=nil end
      elseif id=="views" then self.nativeViews=not self.nativeViews self.nativeRadars=false self.nativeViewFirst=1
      elseif id:sub(1,5)=="page:" then self.page=id:sub(6) self.scroll=1 self.tracking=false self.nativeViews=false
      elseif id:sub(1,8)=="station:" then
        local station=(self.snapshot.radars or {})[tonumber(id:sub(9))]
        if station then self.radarId=station.id end self.nativeRadars=false
      elseif self.nativeViews or self.nativeRadars then self.nativeViews=false self.nativeRadars=false
      elseif id=="radarNext" then self.nativeRadars=true self.nativeViews=false self.nativeViewFirst=1
      elseif id=="radar" or id=="three" then self.page=id
      elseif id=="all" or id:sub(1,7)=="filter:" then
        filter.toggle(self.filters,id=="all" and "all" or id:sub(8))
        local target=find(self.snapshot.targets,self.targetId)
        if target and not filter.visible(target,self.filters) then api.select(self.targetId) end
      elseif id:sub(1,4)=="row:" then
        local rows=self.page=="targets" and filter.targets(self.snapshot.targets,self.filters) or self.page=="cannons" and self.snapshot.cannons or self.page=="network" and (self.networkSnapshot or {}).nodes or self.snapshot.devices
        local row=rows[tonumber(id:sub(5))]
        if row then
          if self.page=="targets" then api.select(row.id)
          elseif self.page=="cannons" then self.cannonId=row.id self.tracking=false
          elseif self.page=="network" then api.station(row.id)
          else self.deviceId=row.id end
        end
      else api.action(id) end
      return true
    end end
    if self.nativeViews or self.nativeRadars then self.nativeViews=false self.nativeRadars=false return true end
    for _,hit in ipairs(self.nativeContacts or {}) do if ui.hit(hit.rect,x,y) then api.select(hit.id) return true end end
    return true
  end
end
return M
]=],
  ["apps/crafttube/app.cfg"] = [=[
{
  id = "crafttube",
  name = "CraftTube",
  version = "0.18.36",
  main = "apps.crafttube.main",
  permissions = { "network.http", "filesystem.read", "filesystem.write" },
}
]=],
  ["apps/crafttube/main.lua"] = [=[
local renderer = require("system.gui.renderer")
local keyboard = require("system.gui.keyboard")
local ui = require("system.gui.components")
local config = require("system.libraries.config")
local httpClient = require("system.network.http_client")
local audiod = require("system.services.audiod")
local appWorker = require("system.libraries.app_worker")

local M = {}

local cfgPath = "/system/config/crafttube.cfg"
local dataPath = "/home/user/config/crafttube.db"
local normalizeVideo

local defaultCfg = {
  provider = "invidious",
  proxy = "https://inv.thepixora.com",
  searchPath = "/api/v1/search?type=video&q=",
  detailsPath = "/api/v1/videos/",
  audioProxy = "http://127.0.0.1:8787",
  audioPath = "/crafttube/audio?id=",
  fallbackProxies = {
    "https://yt.chocolatemoo53.com",
    "https://invidious.f5.si",
  },
}

local function urlEncode(text)
  text = tostring(text or "")
  text = text:gsub("\n", "\r\n")
  text = text:gsub("([^%w%-%_%.%~ ])", function(ch)
    return string.format("%%%02X", string.byte(ch))
  end)
  return text:gsub(" ", "+")
end

local function loadCfg()
  local cfg = config.load(cfgPath, {})
  if type(cfg)~="table" then cfg={} end
  for key, value in pairs(defaultCfg) do
    if type(cfg[key])~=type(value) or cfg[key] == "" then cfg[key] = value end
  end
  return cfg
end

local function saveCfg(cfg)
  return config.save(cfgPath, cfg)
end

local function loadData()
  local data=config.load(dataPath, { favorites = {}, history = {} })
  if type(data)~="table" then data={} end
  for _,key in ipairs({"favorites","history"}) do
    local rows={}
    if type(data[key])=="table" then
      for i=1,math.min(30,#data[key]) do
        local row=data[key][i]
        if type(row)=="table" and type(row.id)=="string" and type(row.title)=="string" then rows[#rows+1]=normalizeVideo(row) end
      end
    end
    data[key]=rows
  end
  return data
end

local function saveData(data)
  return config.save(dataPath, data)
end

normalizeVideo = function(raw)
  if type(raw) ~= "table" then return nil end
  local id = raw.id
  local snippet=type(raw.snippet)=="table" and raw.snippet or {}
  if type(id) == "table" then id = id.videoId or id.id end
  id = raw.videoId or raw.video_id or id
  local title = raw.title or raw.name or snippet.title
  if not id and raw.url then id = tostring(raw.url):match("[?&]v=([%w%-_]+)") or tostring(raw.url):match("youtu%.be/([%w%-_]+)") end
  if not title or title == "" then title = id or "Untitled" end
  local duration = raw.duration or raw.length or raw.lengthText
  if not duration and raw.lengthSeconds then
    local seconds = tonumber(raw.lengthSeconds) or 0
    if seconds~=seconds or seconds==math.huge or seconds==-math.huge then seconds=0 end
    seconds=math.max(0,math.min(86400,math.floor(seconds)))
    duration = string.format("%d:%02d", math.floor(seconds / 60), seconds % 60)
  end
  return {
    id = tostring(id or title),
    title = tostring(title),
    channel = tostring(raw.channel or raw.channelTitle or raw.author or snippet.channelTitle or "-"),
    description = tostring(raw.description or snippet.description or ""),
    duration = tostring(duration or "-"),
    views = tostring(raw.viewCountText or raw.views or raw.viewCount or "-"),
    published = tostring(raw.publishedText or raw.published or ""),
    url = tostring(raw.url or ("https://www.youtube.com/watch?v=" .. tostring(id or ""))),
  }
end

local function listFromJson(json)
  local source = type(json)=="table" and (json.items or json.results or json.videos or json)
  local out = {}
  if type(source) == "table" then
    for i=1,math.min(#source,100) do
      local item=source[i]
      local video = normalizeVideo(item)
      if video then table.insert(out, video) end
    end
  end
  return out
end

local function findById(rows, id)
  for _, item in ipairs(rows or {}) do
    if item.id == id then return item end
  end
  return nil
end

local function addUnique(list, item)
  for i = #list, 1, -1 do
    if list[i].id == item.id then table.remove(list, i) end
  end
  table.insert(list, 1, item)
  while #list > 30 do table.remove(list) end
end

local function splitLines(text, width)
  local rows = {}
  width = math.max(8, width or 40)
  for raw in tostring(text or ""):gmatch("[^\r\n]+") do
    local line = raw:gsub("%s+", " ")
    while #line > width do
      table.insert(rows, line:sub(1, width))
      line = line:sub(width + 1)
    end
    table.insert(rows, line)
  end
  if #rows == 0 then table.insert(rows, "") end
  return rows
end

function M.run(ctx)
  local app = {
    cfg = loadCfg(),
    data = loadData(),
    mode = "search",
    input = (ctx.args and ctx.args.query) or "",
    status = "Configure proxy in Settings or paste it here.",
    selected = nil,
    rows = {},
    scroll = 1,
    keyboard = {},
  }
  local worker
  local function enqueue(action)
    local cfg={}
    for key,value in pairs(app.cfg) do cfg[key]=value end
    local ok,err=worker:submit({action=action,input=app.input,cfg=cfg,video=findById(app.rows,app.selected)})
    app.status=ok and "Loading..." or tostring(err)
  end

  local actions = {
    { id = "search", label = "Search" },
    { id = "play", label = "Play" },
    { id = "proxy", label = "Proxy" },
    { id = "audio", label = "Audio" },
    { id = "fav", label = "Fav" },
    { id = "history", label = "History" },
    { id = "details", label = "Details" },
  }

  local function selectedVideo()
    return findById(app.rows, app.selected)
  end

  local function replaceSelected(video)
    for i, item in ipairs(app.rows) do
      if item.id == video.id then
        app.rows[i] = video
        return
      end
    end
  end

  local function showRows(rows, status)
    app.rows = rows or {}
    app.scroll = 1
    app.selected = app.rows[1] and app.rows[1].id or nil
    app.status = status or tostring(#app.rows) .. " results"
  end

  local function searchWithProxy(proxy,request)
    if type(proxy)~="string" then return nil,"Invalid proxy" end
    local url = proxy .. request.cfg.searchPath .. urlEncode(request.input)
    local allowed, denied = ctx.security.require("network.http", url)
    if not allowed then return nil, denied end
    local response, err = httpClient.json(url,{timeout=5,maxBytes=1048576})
    if not response then return nil, err end
    return listFromJson(response.json)
  end

  local function search(request)
    if request.input == "" then app.status = "Enter search text" return end
    local proxies = { request.cfg.proxy }
    for i=1,math.min(4,#request.cfg.fallbackProxies) do table.insert(proxies,request.cfg.fallbackProxies[i]) end
    app.status = "Searching..."
    local lastErr
    for _, proxy in ipairs(proxies) do
      local rows, err = searchWithProxy(proxy,request)
      if rows and #rows > 0 then
        if app.cfg.proxy==request.cfg.proxy then app.cfg.proxy = proxy saveCfg(app.cfg) end
        showRows(rows, "Search complete via " .. proxy)
        return
      end
      lastErr = err or "no results"
    end
    app.status = tostring(lastErr or "no results")
  end

  local function toggleFavorite()
    local video = selectedVideo()
    if not video then app.status = "No video selected" return end
    addUnique(app.data.favorites, video)
    saveData(app.data)
    app.status = "Favorite saved"
  end

  local function openVideo(request)
    local video = request.video
    if not video then app.status = "No video selected" return end
    if request.cfg.proxy ~= "" and request.cfg.detailsPath ~= "" then
      local detailsUrl = request.cfg.proxy .. request.cfg.detailsPath .. urlEncode(video.id)
      local allowed,denied = ctx.security.require("network.http", detailsUrl)
      if not allowed then app.status=tostring(denied) return end
      local response,err = httpClient.json(detailsUrl,{timeout=8,maxBytes=1048576})
      if not response then app.status=tostring(err) return end
      if response and type(response.json)=="table" then
        local detail = normalizeVideo(response.json.video or response.json.item or response.json)
        if detail then
          video = detail
          replaceSelected(video)
        end
      end
    end
    addUnique(app.data.history, video)
    saveData(app.data)
    app.status = "Opened details"
  end

  local function playSelected(request)
    local video = request.video
    if not video then app.status = "No video selected" return end
    if request.cfg.audioProxy == "" then
      app.status = "Start DFPWM proxy on http://127.0.0.1:8787"
      return
    end
    local base = request.cfg.audioProxy:gsub("/+$", "")
    local audioPath = request.cfg.audioPath
    local url = base .. audioPath .. urlEncode(video.id)
    local allowed, denied = ctx.security.require("network.http", url)
    if not allowed then app.status = denied return end
    app.status = "Downloading DFPWM audio..."
    local response, err = httpClient.get(url, { binary = true,maxBytes=4194304,timeout=125 })
    if not response then app.status = tostring(err) return end
    if not fs.exists("/var/tmp") then fs.makeDir("/var/tmp") end
    local path = "/var/tmp/crafttube_audio_"..tostring(ctx.pid)..".dfpwm"
    local handle = fs.open(path, "wb")
    if not handle then app.status = "Cannot write audio temp file" return end
    local wrote,writeErr=pcall(handle.write,response.body)
    pcall(handle.close)
    if not wrote then app.status=tostring(writeErr) return end
    local ok, playErr = audiod.playDfPWM(path)
    app.status = ok and ("Playing " .. video.title) or tostring(playErr)
  end

  local function saveProxy()
    if app.input ~= "" then
      if app.mode == "audio" then
        app.cfg.audioProxy = app.input:gsub("/+$", "")
        app.cfg.audioPath = app.cfg.audioPath or defaultCfg.audioPath
      else
        app.cfg.proxy = app.input:gsub("/+$", "")
        app.cfg.searchPath = app.cfg.searchPath or defaultCfg.searchPath
        app.cfg.detailsPath = app.cfg.detailsPath or defaultCfg.detailsPath
      end
      saveCfg(app.cfg)
      app.status = app.mode == "audio" and "Audio proxy saved" or "Proxy saved"
    end
  end

  app.keyboard.onText = function(ch) app.input = app.input .. ch end
  app.keyboard.onBackspace = function() app.input = app.input:sub(1, -2) end
  app.keyboard.onEnter = function()
    if app.mode == "proxy" or app.mode == "audio" then saveProxy() else enqueue("search") end
  end

  function app:draw(w, h)
    self.toolbar = ui.toolbar(1, 1, w, actions)
    local kbH = keyboard.height()
    local selected = selectedVideo()
    local inputLabel = self.mode == "proxy" and "Proxy" or (self.mode == "audio" and "Audio proxy" or "Search")
    ui.input(1, 2, w, inputLabel, self.input, true)
    renderer.writeAt(1, 3, renderer.crop("Status: " .. self.status, w), colors.black, colors.lightGray)
    local cardH = 3
    local listH = math.max(1, h - kbH - 10)
    local visible = math.max(1, math.floor(listH / cardH))
    for i = 1, visible do
      local item = self.rows[self.scroll + i - 1]
      local y = 4 + (i - 1) * cardH
      if item then
        local bg = item.id == self.selected and colors.cyan or colors.lightGray
        renderer.writeAt(1, y, renderer.crop("[" .. tostring(self.scroll + i - 1) .. "] " .. item.title, w), colors.black, bg)
        renderer.writeAt(1, y + 1, renderer.crop("    " .. item.channel .. "   " .. item.duration .. "   " .. item.views, w), colors.gray, colors.lightGray)
        renderer.writeAt(1, y + 2, renderer.crop("    " .. item.url, w), colors.gray, colors.lightGray)
      else
        renderer.writeAt(1, y, renderer.crop("No result. Set a proxy, then search.", w), colors.gray, colors.lightGray)
      end
    end
    local detailY = 4 + visible * cardH
    if selected then
      renderer.writeAt(1, detailY, renderer.crop("Selected: " .. selected.title, w), colors.white, colors.gray)
      renderer.writeAt(1, detailY + 1, renderer.crop(selected.channel .. "  " .. selected.duration .. "  " .. selected.views .. "  " .. selected.published, w), colors.black, colors.lightGray)
      local lines = splitLines(selected.description, w)
      renderer.writeAt(1, detailY + 2, renderer.crop(lines[1] or "", w), colors.gray, colors.lightGray)
      renderer.writeAt(1, detailY + 3, renderer.crop("Play requires DFPWM proxy: " .. tostring(self.cfg.audioProxy or "-"), w), colors.gray, colors.lightGray)
    else
      renderer.writeAt(1, detailY, renderer.crop("CraftTube is the YouTube app for MintCraft OS.", w), colors.white, colors.gray)
      renderer.writeAt(1, detailY + 1, renderer.crop("It needs a proxy/API because CC:Tweaked cannot run YouTube web UI.", w), colors.gray, colors.lightGray)
      renderer.writeAt(1, detailY + 2, renderer.crop("Default API: " .. tostring(self.cfg.proxy), w), colors.gray, colors.lightGray)
    end
    self.keyboard.x = 1
    self.keyboard.y = h - kbH + 1
    self.keyboard.hint = self.mode == "proxy" and "Proxy URL" or (self.mode == "audio" and "DFPWM audio proxy URL" or "Search")
    keyboard.draw(1, self.keyboard.y, w, self.keyboard)
  end

  function app:handle(event)
    if event.name == "mouse_scroll" then
      self.scroll = math.max(1, self.scroll + event.args[1])
      return true
    elseif event.name == "char" then
      self.input = self.input .. event.args[1]
      return true
    elseif event.name == "key" then
      local key = event.args[1]
      if key == keys.backspace then self.input = self.input:sub(1, -2) return true end
      if key == keys.enter then self.keyboard.onEnter() return true end
    elseif event.name == "mouse_click" then
      local _, x, y = table.unpack(event.args)
      if event.monitorTouch and keyboard.handle(event, self.keyboard) then return true end
      local action = ui.toolbarHit(self.toolbar, x, y)
      if action == "search" then self.mode = "search" enqueue("search") return true end
      if action == "play" then enqueue("play") return true end
      if action == "proxy" then self.mode = "proxy" self.input = self.cfg.proxy or "" return true end
      if action == "audio" then self.mode = "audio" self.input = self.cfg.audioProxy or "" return true end
      if action == "fav" then toggleFavorite() return true end
      if action == "history" then showRows(self.data.history, "History") return true end
      if action == "details" then
        local video = selectedVideo()
        if video then enqueue("details") end
        return true
      end
      if y >= 4 then
        local item = self.rows[self.scroll + math.floor((y - 4) / 3)]
        if item then self.selected = item.id enqueue("details") return true end
      end
    end
    return false
  end

  showRows(app.data.favorites, "Favorites")
  local sw, sh = term.getSize()
  local win = ctx.windowManager:create({ title = "CraftTube", w = math.min(78, sw - 4), h = math.min(24, sh - 3), x = 4, y = 3, app = app })
  worker=appWorker.new(ctx,"CraftTube requests",function(request)
    if request.action=="search" then search(request)
    elseif request.action=="details" then openVideo(request)
    elseif request.action=="play" then playSelected(request) end
