        for _,name in ipairs(fs.list(item.from)) do
          count=count+1
          if count>1024 then error("Transfer exceeds 1024 items; use smaller folders",0) end
          pending[#pending+1]={from=fileNames.absolute(fs.combine(item.from,name)),
