    scale = kind=="monitor" and scale or nil,
    width = w,
    height = h,
    monitorSide = kind=="monitor" and side or nil,
    terminalSide = kind=="terminal" and side or nil,
    color = color,
    keyboard = kind=="terminal",
    mouse = kind=="terminal" and color,
