  ["system/wm/window.lua"] = [=[
local theme = require("system.gui.theme")
local renderer = require("system.gui.renderer")

local Window = {}
Window.__index = Window

function Window.new(opts)
  for _,key in ipairs({"minPixelWidth","minPixelHeight"}) do
    local value=opts[key]
    assert(value==nil or type(value)=="number" and value>0 and value<=4096 and value%1==0,"Invalid "..key)
  end
  local w, h = term.getSize()
  local width = opts.w or math.min(38, w - 8)
  local height = opts.h or math.min(12, h - 5)
  width = math.max(12, math.min(width, w))
  height = math.max(5, math.min(height, h - 1))
  return setmetatable({
    id = opts.id,
    title = tostring(opts.title or "Window"),
    x = opts.x or 6,
    y = opts.y or 3,
    w = width,
    h = height,
    minimized = false,
    maximized = false,
    closed = false,
    dragging = false,
    movePending = false,
    minimizeBox = nil,
    maximizeBox = nil,
    closeBox = nil,
    previousBounds = nil,
    app = opts.app,
    ownerPid = opts.ownerPid,
    minPixelWidth = opts.minPixelWidth,
    minPixelHeight = opts.minPixelHeight,
    onError = opts.onError,
    dirty = true,
  }, Window)
end

function Window:crash(err)
  self.closed = true
  if self.onError then
    pcall(self.onError, err)
  end
end

function Window:requestClose()
  if self.app and self.app.canClose then
    local ok,allowed=pcall(self.app.canClose,self.app,self)
    self.dirty=true
    if not ok then self:crash("close: "..tostring(allowed)) return false end
    if allowed==false then return false end
  end
  self.closed=true
  return true
end

function Window:clamp()
  -- Pixel bounds are clamped by the graphical workspace. Its virtual text
  -- clients may have more cells than the physical terminal's text-mode grid.
  if self.pixelManaged then return end
  local sw, sh = term.getSize()
  self.w = math.min(self.w, sw)
  self.h = math.min(self.h, math.max(1, sh - 1))
  if self.maximized and not self.pixelManaged then
    self.w, self.h = sw, math.max(1, sh - 1)
  end
  local maxX = math.max(1, sw - self.w + 1)
  local maxY = math.max(1, sh - self.h)
  self.x = math.max(1, math.min(self.x, maxX))
  self.y = math.max(1, math.min(self.y, maxY))
end

function Window:contains(x, y)
  if self.closed or self.minimized then return false end
  return x >= self.x and x < self.x + self.w and y >= self.y and y < self.y + self.h
end

function Window:titleContains(x, y)
  return y == self.y and x >= self.x and x < self.x + self.w
end

function Window:boxHit(box, x, y)
  return box and x >= box.x and x < box.x + box.w and y == box.y
end

function Window:updateControls()
  local y = self.y
  self.minimizeBox = { x = self.x + self.w - 6, y = y, w = 2 }
  self.maximizeBox = { x = self.x + self.w - 4, y = y, w = 2 }
  self.closeBox = { x = self.x + self.w - 2, y = y, w = 2 }
end

function Window:toggleMaximize()
  if self.pixelController then self.pixelController() return end
  if self.maximized and self.previousBounds then
    self.x = self.previousBounds.x
    self.y = self.previousBounds.y
    self.w = self.previousBounds.w
    self.h = self.previousBounds.h
    self.maximized = false
    self.previousBounds = nil
  else
    self.previousBounds = { x = self.x, y = self.y, w = self.w, h = self.h }
    local sw, sh = term.getSize()
    self.x, self.y = 1, 1
    self.w, self.h = sw, math.max(5, sh - 1)
    self.maximized = true
  end
  self:clamp()
end

function Window:draw()
  if self.closed or self.minimized then return end
  self:clamp()
  if self.pixelNative then
    if self.dirty then self.surfaceRevision=(self.surfaceRevision or 0)+1 self.dirty=false end
    return
  end
  local _, screenHeight = term.getSize()
  renderer.fill(self.x + 1, self.y + 1, self.w, math.min(self.h, screenHeight - self.y - 1), theme.get("shadow"))
  renderer.fill(self.x, self.y, self.w, self.h, theme.get("windowBg"))
  self:updateControls()
  local title = self.movePending and " Tap destination" or (" " .. self.title)
  renderer.writeAt(self.x, self.y, renderer.crop(title, self.w - 7), theme.get("titleFg"), theme.get("titleBg"))
  renderer.writeAt(self.minimizeBox.x, self.y, " -", theme.get("titleFg"), theme.get("titleBg"))
  renderer.writeAt(self.maximizeBox.x, self.y, self.maximized and "[]" or "[]", theme.get("titleFg"), theme.get("titleBg"))
  renderer.writeAt(self.closeBox.x, self.y, " X", theme.get("titleFg"), theme.get("titleBg"))

  if self.app and self.app.draw and self.w > 2 and self.h > 2 then
    local parent = term.current()
    if not self.surface or self.surfaceParent ~= parent then
      self.surface = window.create(parent, self.x + 1, self.y + 1, self.w - 2, self.h - 2, false)
      if parent.mintcraftPixelBuffer then require("system.graphics.legacy").buffer(self.surface) end
      self.surfaceParent = parent
      self.surfaceBounds = nil
    end
    local target = self.surface
    target.setVisible(false)
    local bounds = self.surfaceBounds
    if not bounds or bounds.x ~= self.x or bounds.y ~= self.y or bounds.w ~= self.w or bounds.h ~= self.h then
      target.reposition(self.x + 1, self.y + 1, self.w - 2, self.h - 2)
      self.surfaceBounds = {x = self.x, y = self.y, w = self.w, h = self.h}
      self.dirty=true
    end
    local ok,err=true,nil
    if self.dirty or self.surfaceTheme~=theme.currentId then
      local previous = term.redirect(target)
      term.setBackgroundColor(theme.get("windowBg"))
      term.setTextColor(theme.get("windowFg"))
      term.clear()
      ok,err=pcall(self.app.draw,self.app,self.w-2,self.h-2)
      term.redirect(previous)
      self.dirty=false self.surfaceTheme=theme.currentId
      if ok then self.surfaceRevision=(self.surfaceRevision or 0)+1 end
    end
    if ok then
      target.setVisible(true)
    else
      self:crash("draw: " .. tostring(err))
    end
  end
end

function Window:handle(event)
  if self.closed then return false end
  local background = event.name == "timer" or event.name == "peripheral" or event.name == "peripheral_detach"
  if self.minimized and not background then return false end
  if event.name == "mouse_click" then
    local button, x, y = table.unpack(event.args)
    if self.movePending then
      self.x = x - math.floor(self.w / 2)
      self.y = y
      self.movePending = false
      self:clamp()
      return true
    end
    self:updateControls()
    if button == 1 and self:boxHit(self.closeBox, x, y) then
      self:requestClose()
      return true
    elseif button == 1 and self:boxHit(self.minimizeBox, x, y) then
      self.minimized = true
      return true
    elseif button == 1 and self:boxHit(self.maximizeBox, x, y) then
      self:toggleMaximize()
      return true
    elseif button == 1 and self:titleContains(x, y) then
      if event.monitorTouch then
        self.movePending = true
        return true
      end
      self.dragging = { dx = x - self.x, dy = y - self.y }
      return true
    end
  elseif event.name == "mouse_drag" and self.dragging then
    local _, x, y = table.unpack(event.args)
    self.x = x - self.dragging.dx
    self.y = y - self.dragging.dy
    self:clamp()
    return true
  elseif event.name == "mouse_up" then
    self.dragging = false
  end

  if self.app and self.app.handle then
    local localEvent = event
    if event.name:match("^mouse_") then
      local args = { table.unpack(event.args) }
      args[2] = args[2] - self.x
      args[3] = args[3] - self.y
      localEvent = {
        name = event.name,
        args = args,
        raw = event.raw,
        monitorTouch = event.monitorTouch,
        monitorSide = event.monitorSide,
        terminalSide = event.terminalSide,
      }
    end
    local ok, handled = pcall(self.app.handle, self.app, localEvent, self)
    if not ok then
      self:crash("handle: " .. tostring(handled))
      return true
    end
    if handled then self.dirty=true end
    return handled
  end
  return false
end

function Window:drawPixels(canvas,w,h,palette)
  local ok,err=pcall(self.app.drawPixels,self.app,canvas,w,h,palette)
  if not ok then self:crash("pixel draw: "..tostring(err)) end
  return ok
end

function Window:handlePixels(event)
  if self.closed or self.minimized then return false end
  local ok,handled=pcall(self.app.handlePixels,self.app,event,self)
  if not ok then self:crash("pixel handle: "..tostring(handled)) return true end
  if handled then self.dirty=true end
  return handled
end

return Window
